import { NgModule } from '@angular/core';
import { RouterModule } from '@angular/router';

/**
 * Routes are registered at the root in app-routing.module.ts; this
 * module exists only to satisfy the AngularModule import in LandingModule.
 * It contributes no routes of its own.
 */
@NgModule({
  imports: [RouterModule.forChild([])],
  exports: [RouterModule]
})
export class LandingRoutingModule { }
